#!/usr/bin/env node

/**
 * Weekly Newsletter Generator & Sender
 * ────────────────────────────────────────────────────────
 * Reads news articles generated by generate-daily-news.mjs,
 * picks the top stories from the past 7 days across all 12 topics,
 * builds a newsletter (HTML + text), saves it to src/data/newsletters/,
 * and sends it to all subscribers via email.
 *
 * Email Providers:
 *   --provider=smtp     (default, Gmail/Outlook, 500/day) → SMTP_HOST, SMTP_USER, SMTP_PASS, SMTP_PORT
 *   --provider=resend   (API, free tier: 100/day)        → RESEND_API_KEY
 *   --provider=mailgun                                   → MAILGUN_API_KEY + MAILGUN_DOMAIN
 *   --provider=console  (just print, don't send)         → no key needed
 *
 * Usage:
 *   node scripts/generate-newsletter.mjs --provider=console              # generate only, print preview
 *   node scripts/generate-newsletter.mjs --provider=smtp --send          # generate + send via Gmail SMTP
 *   node scripts/generate-newsletter.mjs --provider=resend --send        # generate + send via Resend API
 *   node scripts/generate-newsletter.mjs --dry-run                       # generate but don't save or send
 *   node scripts/generate-newsletter.mjs --max-per-topic=2               # limit stories per topic
 *   node scripts/generate-newsletter.mjs --send                          # actually send emails (required flag)
 *
 * SMTP Setup (Gmail, no API key needed):
 *   1. Enable 2FA on your Google account
 *   2. Go to https://myaccount.google.com/apppasswords
 *   3. Create an app password (select "Mail")
 *   4. Set in .env:
 *      SMTP_HOST=smtp.gmail.com
 *      SMTP_PORT=465
 *      SMTP_USER=your-email@gmail.com
 *      SMTP_PASS=your-16-char-app-password
 *
 * Requires:
 *   SMTP_* vars (or RESEND_API_KEY or MAILGUN_API_KEY + MAILGUN_DOMAIN) in .env
 *   Subscribers stored in src/data/subscribers/subscribers.json
 */

import { readFileSync, writeFileSync, existsSync, readdirSync, mkdirSync } from 'fs';
import { resolve, dirname, join } from 'path';
import { fileURLToPath } from 'url';

let nodemailer = null;
try {
  nodemailer = (await import('nodemailer')).default;
} catch {
  // nodemailer not installed — SMTP provider will be unavailable
}

const __dirname = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(__dirname, '..');

// ─── Configuration ───────────────────────────────────────────────────────────

const ARTICLES_DIR = resolve(projectRoot, 'src', 'data', 'news', 'articles');
const NEWSLETTERS_DIR = resolve(projectRoot, 'src', 'data', 'newsletters');
const SUBSCRIBERS_FILE = resolve(projectRoot, 'src', 'data', 'subscribers', 'subscribers.json');

const DAYS_BACK = 7;
const DEFAULT_MAX_PER_TOPIC = 2;
const MAX_TOTAL_STORIES = 12;

const SITE_NAME = 'TechNanoAI';
const SITE_URL = 'https://technanoai.com';
const FROM_EMAIL = 'newsletter@technanoai.com';
const FROM_NAME = 'TechNanoAI Weekly';

// ─── Topic Metadata (mirrors generate-daily-news.mjs) ────────────────────────

const TOPIC_META = {
  ai:          { label: 'AI',                   icon: '🤖', color: '#3b82f6' },
  cybersecurity: { label: 'Cybersecurity',      icon: '🛡️', color: '#ef4444' },
  space:       { label: 'Space',                icon: '🚀', color: '#06b6d4' },
  biotech:     { label: 'Biotech',              icon: '🧬', color: '#10b981' },
  nuclear:     { label: 'Nuclear',              icon: '☢️', color: '#f59e0b' },
  energy:      { label: 'Energy Storage',       icon: '🔋', color: '#f97316' },
  robotics:    { label: 'Robotics',             icon: '🦾', color: '#ec4899' },
  av:          { label: 'Autonomous Vehicles',  icon: '🚗', color: '#8b5cf6' },
  quantum:     { label: 'Quantum',              icon: '💠', color: '#a78bfa' },
  materials:   { label: 'Materials',            icon: '🔬', color: '#f43f5e' },
  bci:         { label: 'BCI',                  icon: '🧠', color: '#0ea5e9' },
  fusion:      { label: 'Fusion',               icon: '⚛️', color: '#fb923c' },
};

// ─── CLI Arguments ───────────────────────────────────────────────────────────

function parseArgs() {
  const args = process.argv.slice(2);
  const parsed = {};
  for (const arg of args) {
    const match = arg.match(/^--(\w[\w-]*)=(.+)$/);
    if (match) {
      parsed[match[1]] = match[2];
    } else if (arg.startsWith('--')) {
      parsed[arg.slice(2)] = true;
    }
  }
  return parsed;
}

function loadEnv() {
  const envPath = resolve(projectRoot, '.env');
  if (existsSync(envPath)) {
    const content = readFileSync(envPath, 'utf-8');
    for (const line of content.split('\n')) {
      const match = line.match(/^([^#=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        const value = match[2].trim().replace(/^["']|["']$/g, '');
        if (!process.env[key]) {
          process.env[key] = value;
        }
      }
    }
  }
}

// ─── Utilities ───────────────────────────────────────────────────────────────

function getIssueNumber() {
  const startDate = new Date('2025-01-06');
  const now = new Date();
  const weeksDiff = Math.floor((now - startDate) / (7 * 24 * 60 * 60 * 1000));
  return weeksDiff + 1;
}

function formatDate(date) {
  return date.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });
}

function isWithinDays(dateStr, days) {
  const articleDate = new Date(dateStr);
  const now = new Date();
  const diffDays = Math.floor((now - articleDate) / (1000 * 60 * 60 * 24));
  return diffDays <= days;
}

// ─── Load Articles ───────────────────────────────────────────────────────────

function loadRecentArticles(maxPerTopic) {
  if (!existsSync(ARTICLES_DIR)) {
    console.warn(`⚠️  Articles directory not found: ${ARTICLES_DIR}`);
    console.warn('   Run generate-daily-news.mjs first to generate articles.');
    return [];
  }

  const files = readdirSync(ARTICLES_DIR).filter(f => f.endsWith('.json'));
  const allArticles = [];

  for (const file of files) {
    try {
      const content = readFileSync(resolve(ARTICLES_DIR, file), 'utf-8');
      const article = JSON.parse(content);
      if (article.date && isWithinDays(article.date, DAYS_BACK)) {
        allArticles.push(article);
      }
    } catch (e) {
      // skip invalid files
    }
  }

  // Group by topic
  const byTopic = {};
  for (const article of allArticles) {
    const topic = article.topic || article.category || 'other';
    if (!byTopic[topic]) byTopic[topic] = [];
    byTopic[topic].push(article);
  }

  // Sort each topic by date (newest first) and limit
  const selected = [];
  for (const [topicId, articles] of Object.entries(byTopic)) {
    articles.sort((a, b) => new Date(b.date) - new Date(a.date));
    const top = articles.slice(0, maxPerTopic);
    selected.push(...top.map(a => ({ ...a, topicId })));
  }

  // Sort all selected by date (newest first)
  selected.sort((a, b) => new Date(b.date) - new Date(a.date));

  // Limit total
  return selected.slice(0, MAX_TOTAL_STORIES);
}

// ─── Newsletter Builder ──────────────────────────────────────────────────────

function buildNewsletterSubject(articles) {
  const topTopics = [...new Set(articles.map(a => a.topicId))].slice(0, 3);
  const topicLabels = topTopics.map(t => TOPIC_META[t]?.label || t);
  const dateStr = formatDate(new Date());

  if (articles.length === 0) {
    return `${SITE_NAME} Weekly — ${dateStr}`;
  }

  if (topicLabels.length === 1) {
    return `This Week in ${topicLabels[0]} — ${dateStr}`;
  } else if (topicLabels.length === 2) {
    return `This Week: ${topicLabels[0]} & ${topicLabels[1]} — ${dateStr}`;
  } else {
    return `This Week: ${topicLabels[0]}, ${topicLabels[1]} & more — ${dateStr}`;
  }
}

function buildNewsletterHTML(articles, issueNum) {
  const dateStr = formatDate(new Date());
  const subject = buildNewsletterSubject(articles);

  const storiesHTML = articles.map(article => {
    const meta = TOPIC_META[article.topicId] || { icon: '📰', label: article.topicId, color: '#64748b' };
    const title = article.title || 'Untitled';
    const excerpt = article.excerpt || article.description || '';
    const link = article.url || `${SITE_URL}/news/${article.slug || ''}`;
    const readTime = article.readTime || '3 min';

    return `
    <tr>
      <td style="padding: 20px 0; border-bottom: 1px solid #1e293b;">
        <table width="100%" cellpadding="0" cellspacing="0">
          <tr>
            <td style="width: 40px; vertical-align: top; padding-right: 12px;">
              <div style="font-size: 24px;">${meta.icon}</div>
            </td>
            <td>
              <div style="font-size: 11px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: ${meta.color}; margin-bottom: 4px;">
                ${meta.label} · ${readTime}
              </div>
              <a href="${link}" style="font-size: 16px; font-weight: 700; color: #f1f5f9; text-decoration: none; line-height: 1.4;">
                ${title}
              </a>
              <p style="font-size: 14px; color: #94a3b8; line-height: 1.6; margin: 6px 0 0;">
                ${excerpt.substring(0, 180)}${excerpt.length > 180 ? '...' : ''}
              </p>
            </td>
          </tr>
        </table>
      </td>
    </tr>`;
  }).join('');

  const topicsCovered = [...new Set(articles.map(a => a.topicId))];
  const topicsBadges = topicsCovered.map(t => {
    const meta = TOPIC_META[t] || { icon: '📰', label: t };
    return `<span style="display: inline-block; font-size: 12px; font-weight: 600; color: #94a3b8; background: #1e293b; border-radius: 999px; padding: 4px 12px; margin: 0 4px 4px 0;">${meta.icon} ${meta.label}</span>`;
  }).join('');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${subject}</title>
</head>
<body style="margin: 0; padding: 0; background: #0a0a0f; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background: #0a0a0f;">
    <tr>
      <td align="center" style="padding: 20px;">
        <table width="600" cellpadding="0" cellspacing="0" style="background: #0d1220; border-radius: 16px; border: 1px solid rgba(255,255,255,0.08); overflow: hidden;">

          <!-- Header -->
          <tr>
            <td style="padding: 32px 40px; text-align: center; background: linear-gradient(135deg, rgba(51,128,255,0.08), rgba(124,58,237,0.08)); border-bottom: 1px solid rgba(255,255,255,0.08);">
              <div style="font-size: 22px; font-weight: 800; color: #f1f5f9; margin-bottom: 4px;">
                ${SITE_NAME} <span style="color: #3380ff;">Weekly</span>
              </div>
              <div style="font-size: 13px; color: #64748b;">Issue #${issueNum} · ${dateStr}</div>
            </td>
          </tr>

          <!-- Subject -->
          <tr>
            <td style="padding: 28px 40px 8px;">
              <h1 style="font-size: 22px; font-weight: 700; color: #f1f5f9; margin: 0; line-height: 1.3;">
                ${subject}
              </h1>
            </td>
          </tr>

          <!-- Topics covered -->
          <tr>
            <td style="padding: 12px 40px 20px;">
              ${topicsBadges}
            </td>
          </tr>

          <!-- Stories -->
          <tr>
            <td style="padding: 0 40px 20px;">
              <table width="100%" cellpadding="0" cellspacing="0">
                ${storiesHTML}
              </table>
            </td>
          </tr>

          <!-- CTA -->
          <tr>
            <td style="padding: 8px 40px 32px; text-align: center;">
              <a href="${SITE_URL}/news" style="display: inline-block; font-size: 14px; font-weight: 700; color: #fff; background: linear-gradient(135deg, #3380ff, #7c3aed); border-radius: 999px; padding: 12px 32px; text-decoration: none;">
                Read All Stories →
              </a>
            </td>
          </tr>

          <!-- Footer -->
          <tr>
            <td style="padding: 24px 40px; border-top: 1px solid rgba(255,255,255,0.08); text-align: center;">
              <p style="font-size: 13px; color: #64748b; margin: 0 0 8px;">
                You're receiving this because you subscribed to ${SITE_NAME}.
              </p>
              <p style="font-size: 12px; color: #475569; margin: 0;">
                <a href="${SITE_URL}/newsletter" style="color: #475569;">Manage preferences</a> ·
                <a href="{{unsubscribe_url}}" style="color: #475569;">Unsubscribe</a> ·
                <a href="${SITE_URL}" style="color: #475569;">${SITE_URL}</a>
              </p>
              <p style="font-size: 11px; color: #334155; margin: 12px 0 0;">
                © ${new Date().getFullYear()} ${SITE_NAME}. All rights reserved.
              </p>
            </td>
          </tr>

        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;
}

function buildNewsletterText(articles, issueNum) {
  const dateStr = formatDate(new Date());
  const subject = buildNewsletterSubject(articles);
  const divider = '─'.repeat(50);

  let text = `${SITE_NAME} Weekly — Issue #${issueNum}\n${dateStr}\n${divider}\n\n${subject}\n\n`;

  if (articles.length === 0) {
    text += 'No major stories this week. See you next Monday!\n\n';
  } else {
    articles.forEach((article, i) => {
      const meta = TOPIC_META[article.topicId] || { icon: '📰', label: article.topicId };
      const link = article.url || `${SITE_URL}/news/${article.slug || ''}`;
      const excerpt = article.excerpt || article.description || '';
      text += `${i + 1}. [${meta.label}] ${article.title}\n`;
      text += `   ${excerpt.substring(0, 150)}${excerpt.length > 150 ? '...' : ''}\n`;
      text += `   ${link}\n\n`;
    });
  }

  text += `${divider}\nRead all stories: ${SITE_URL}/news\n`;
  text += `Manage preferences: ${SITE_URL}/newsletter\n`;
  text += `Unsubscribe: {{unsubscribe_url}}\n`;
  text += `© ${new Date().getFullYear()} ${SITE_NAME}\n`;

  return text;
}

// ─── Subscriber Management ───────────────────────────────────────────────────

function loadSubscribers() {
  if (!existsSync(SUBSCRIBERS_FILE)) {
    return [];
  }
  try {
    const content = readFileSync(SUBSCRIBERS_FILE, 'utf-8');
    return JSON.parse(content);
  } catch (e) {
    console.warn(`⚠️  Failed to parse subscribers file: ${e.message}`);
    return [];
  }
}

// ─── Email Providers ─────────────────────────────────────────────────────────

async function sendViaSMTP(subscribers, subject, html, text) {
  if (!nodemailer) {
    throw new Error('nodemailer not installed. Run: npm install nodemailer');
  }

  const host = process.env.SMTP_HOST;
  const port = parseInt(process.env.SMTP_PORT || '465', 10);
  const user = process.env.SMTP_USER;
  const pass = process.env.SMTP_PASS;

  if (!host || !user || !pass) {
    throw new Error('SMTP_HOST, SMTP_USER, and SMTP_PASS not found in .env');
  }

  const transporter = nodemailer.createTransport({
    host,
    port,
    secure: port === 465,
    auth: { user, pass },
  });

  // Verify connection
  await transporter.verify();
  console.log('   ✅ SMTP connection verified');

  let totalSent = 0;
  let totalFailed = 0;

  for (const sub of subscribers) {
    const unsubUrl = `${SITE_URL}/unsubscribe?email=${encodeURIComponent(sub.email)}`;
    const personalizedHtml = html.replace(/{{unsubscribe_url}}/g, unsubUrl);
    const personalizedText = text.replace(/{{unsubscribe_url}}/g, unsubUrl);

    try {
      await transporter.sendMail({
        from: `${FROM_NAME} <${user}>`,
        to: sub.email,
        subject,
        html: personalizedHtml,
        text: personalizedText,
        headers: {
          'List-Unsubscribe': `<${unsubUrl}>`,
        },
      });
      totalSent++;
      if (totalSent % 10 === 0 || totalSent === subscribers.length) {
        console.log(`  📧 Sent ${totalSent}/${subscribers.length} emails`);
      }
      // Rate limit: 500/day for Gmail, pace at 1 per 1.5s to be safe
      if (totalSent < subscribers.length) {
        await new Promise(r => setTimeout(r, 1500));
      }
    } catch (err) {
      totalFailed++;
      console.warn(`  ⚠️  Failed to send to ${sub.email}: ${err.message}`);
    }
  }

  console.log(`   ✅ Sent ${totalSent} emails, ${totalFailed} failed`);
  return totalSent;
}

async function sendViaResend(apiKey, subscribers, subject, html, text) {
  const RESEND_URL = 'https://api.resend.com/emails/batch';

  // Resend batch supports up to 100 emails per request
  const batches = [];
  for (let i = 0; i < subscribers.length; i += 100) {
    batches.push(subscribers.slice(i, i + 100));
  }

  let totalSent = 0;
  for (const batch of batches) {
    const emails = batch.map(sub => ({
      from: `${FROM_NAME} <${FROM_EMAIL}>`,
      to: [sub.email],
      subject,
      html,
      text,
      headers: {
        'List-Unsubscribe': `<${SITE_URL}/unsubscribe?email=${encodeURIComponent(sub.email)}>`,
      },
      tags: [{ name: 'newsletter', value: 'weekly' }],
    }));

    const response = await fetch(RESEND_URL, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(emails),
    });

    if (!response.ok) {
      const error = await response.text();
      throw new Error(`Resend API error (${response.status}): ${error}`);
    }

    totalSent += batch.length;
    console.log(`  📧 Sent ${batch.length} emails (total: ${totalSent}/${subscribers.length})`);
  }

  return totalSent;
}

async function sendViaMailgun(apiKey, domain, subscribers, subject, html, text) {
  const MAILGUN_URL = `https://api.mailgun.net/v3/${domain}/messages`;

  // Mailgun supports batch sending with recipient variables
  const recipientVariables = {};
  const recipients = [];
  for (const sub of subscribers) {
    recipients.push(sub.email);
    recipientVariables[sub.email] = { unsubscribe_url: `${SITE_URL}/unsubscribe?email=${encodeURIComponent(sub.email)}` };
  }

  // Send in batches of 1000 (Mailgun limit)
  let totalSent = 0;
  for (let i = 0; i < recipients.length; i += 1000) {
    const batchRecipients = recipients.slice(i, i + 1000);
    const batchVars = {};
    for (const email of batchRecipients) {
      batchVars[email] = recipientVariables[email];
    }

    const formData = new URLSearchParams();
    formData.append('from', `${FROM_NAME} <${FROM_EMAIL}>`);
    formData.append('to', batchRecipients.join(','));
    formData.append('subject', subject);
    formData.append('html', html.replace(/{{unsubscribe_url}}/g, '%recipient.unsubscribe_url%'));
    formData.append('text', text.replace(/{{unsubscribe_url}}/g, '%recipient.unsubscribe_url%'));
    formData.append('recipient-variables', JSON.stringify(batchVars));
    formData.append('o:tag', 'newsletter');

    const response = await fetch(MAILGUN_URL, {
      method: 'POST',
      headers: {
        'Authorization': `Basic ${Buffer.from(`api:${apiKey}`).toString('base64')}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: formData.toString(),
    });

    if (!response.ok) {
      const error = await response.text();
      throw new Error(`Mailgun API error (${response.status}): ${error}`);
    }

    totalSent += batchRecipients.length;
    console.log(`  📧 Sent ${batchRecipients.length} emails (total: ${totalSent}/${subscribers.length})`);
  }

  return totalSent;
}

// ─── Main ────────────────────────────────────────────────────────────────────

async function main() {
  loadEnv();

  const args = parseArgs();
  const providerKey = args.provider || 'smtp';
  const maxPerTopic = parseInt(args['max-per-topic'] || String(DEFAULT_MAX_PER_TOPIC), 10);
  const dryRun = args['dry-run'] || false;
  const shouldSend = args['send'] || false;

  const issueNum = getIssueNumber();
  const dateStr = formatDate(new Date());

  console.log('\n' + '═'.repeat(60));
  console.log(`  📰 ${SITE_NAME} Weekly Newsletter Generator`);
  console.log(`  Issue #${issueNum} · ${dateStr}`);
  console.log('═'.repeat(60) + '\n');

  // ── Step 1: Load recent articles ──
  console.log('📋 Step 1: Loading recent articles...');
  const articles = loadRecentArticles(maxPerTopic);
  console.log(`   → Found ${articles.length} articles from the past ${DAYS_BACK} days`);

  if (articles.length === 0) {
    console.log('\n⚠️  No articles found. Run generate-daily-news.mjs first.');
    console.log('   The newsletter will still be generated but with no stories.\n');
  } else {
    const topicsCovered = [...new Set(articles.map(a => a.topicId))];
    console.log(`   → Covering ${topicsCovered.length} topics: ${topicsCovered.map(t => TOPIC_META[t]?.label || t).join(', ')}`);
  }

  // ── Step 2: Build newsletter ──
  console.log('\n📝 Step 2: Building newsletter...');
  const subject = buildNewsletterSubject(articles);
  const html = buildNewsletterHTML(articles, issueNum);
  const text = buildNewsletterText(articles, issueNum);

  console.log(`   → Subject: ${subject}`);
  console.log(`   → HTML length: ${html.length} chars`);
  console.log(`   → Text length: ${text.length} chars`);

  // ── Step 3: Save newsletter JSON ──
  if (!dryRun) {
    console.log('\n💾 Step 3: Saving newsletter...');
    if (!existsSync(NEWSLETTERS_DIR)) {
      mkdirSync(NEWSLETTERS_DIR, { recursive: true });
    }

    const newsletterData = {
      issue: issueNum,
      date: new Date().toISOString().split('T')[0],
      subject,
      articleCount: articles.length,
      topicsCovered: [...new Set(articles.map(a => a.topicId))],
      articles: articles.map(a => ({
        title: a.title,
        slug: a.slug,
        topic: a.topicId,
        excerpt: a.excerpt || a.description || '',
        url: a.url || `${SITE_URL}/news/${a.slug || ''}`,
        date: a.date,
      })),
      html,
      text,
    };

    const newsletterFile = resolve(NEWSLETTERS_DIR, `issue-${issueNum}-${new Date().toISOString().split('T')[0]}.json`);
    writeFileSync(newsletterFile, JSON.stringify(newsletterData, null, 2), 'utf-8');
    console.log(`   → Saved to: src/data/newsletters/issue-${issueNum}-${new Date().toISOString().split('T')[0]}.json`);

    // Also update the "latest" pointer
    const latestFile = resolve(NEWSLETTERS_DIR, 'latest.json');
    writeFileSync(latestFile, JSON.stringify({
      issue: issueNum,
      date: newsletterData.date,
      subject,
      articleCount: articles.length,
      topicsCovered: newsletterData.topicsCovered,
      articles: newsletterData.articles,
    }, null, 2), 'utf-8');
    console.log('   → Updated latest.json pointer');
  } else {
    console.log('\n💾 Step 3: Skipped (dry-run mode)');
  }

  // ── Step 4: Send emails ──
  if (!shouldSend) {
    console.log('\n📧 Step 4: Skipped (add --send flag to actually send emails)');
    console.log('   Preview the newsletter in the saved JSON file.\n');
  } else if (dryRun) {
    console.log('\n📧 Step 4: Skipped (dry-run mode)');
  } else if (providerKey === 'console') {
    console.log('\n📧 Step 4: Console mode — printing newsletter preview:');
    console.log('\n' + '─'.repeat(60));
    console.log(text);
    console.log('─'.repeat(60) + '\n');
  } else {
    console.log(`\n📧 Step 4: Sending emails via ${providerKey}...`);

    const subscribers = loadSubscribers();
    const activeSubscribers = subscribers.filter(s => s.active !== false);

    if (activeSubscribers.length === 0) {
      console.log('   ⚠️  No active subscribers found. Skipping send.');
      console.log(`   → Subscribers file: ${SUBSCRIBERS_FILE}`);
    } else {
      console.log(`   → ${activeSubscribers.length} active subscribers`);

      if (providerKey === 'smtp') {
        if (!nodemailer) {
          console.error('   ❌ nodemailer not installed. Run: npm install nodemailer');
          process.exit(1);
        }
        const sent = await sendViaSMTP(activeSubscribers, subject, html, text);
        console.log(`   ✅ Sent ${sent} emails successfully!`);
      } else if (providerKey === 'resend') {
        const apiKey = process.env.RESEND_API_KEY;
        if (!apiKey) {
          console.error('   ❌ RESEND_API_KEY not found in .env');
          process.exit(1);
        }
        const sent = await sendViaResend(apiKey, activeSubscribers, subject, html, text);
        console.log(`   ✅ Sent ${sent} emails successfully!`);
      } else if (providerKey === 'mailgun') {
        const apiKey = process.env.MAILGUN_API_KEY;
        const domain = process.env.MAILGUN_DOMAIN;
        if (!apiKey || !domain) {
          console.error('   ❌ MAILGUN_API_KEY or MAILGUN_DOMAIN not found in .env');
          process.exit(1);
        }
        const sent = await sendViaMailgun(apiKey, domain, activeSubscribers, subject, html, text);
        console.log(`   ✅ Sent ${sent} emails successfully!`);
      } else {
        console.error(`   ❌ Unknown provider: ${providerKey}`);
        console.error('   Available: smtp, resend, mailgun, console');
        process.exit(1);
      }
    }
  }

  // ── Summary ──
  console.log('\n' + '═'.repeat(60));
  console.log('  ✅ Newsletter generation complete!');
  console.log(`  Issue #${issueNum} · ${articles.length} stories · ${dateStr}`);
  console.log('═'.repeat(60) + '\n');
}

main().catch(err => {
  console.error(`\n❌ Fatal error: ${err.message}\n`);
  process.exit(1);
});
